    Object.assign(this.el, { under42e: q('under42e'), drop42e: q('drop42e') });      // đợt 42 E
    if (this.el.tocSau) this.el.tocSau.style.display = 'none';   // slot kiểu cũ: rig tự sinh tóc sau đầu
